-- Human-readable booking reference, e.g. BK-2026-00042.
--
-- Guest emails showed the booking's primary key, a 36-character UUID that is
-- correct but impossible to read out over the phone. The reference is what
-- guests see and quote; the UUID stays the key everything joins on
-- (email_sends.booking_id, review_requests.booking_id, audit logs).
--
-- Generated by the database, not the app, so every create path — Stripe
-- webhook, Uplisting webhook, admin create, CSV import — gets one without
-- remembering to. The year is the New Zealand calendar year at creation
-- (Render runs in UTC, 12–13h behind). The counter is one global sequence,
-- so numbers never repeat across years either.
--
-- Idempotent, so a re-run against an already-migrated database is a no-op.

CREATE SEQUENCE IF NOT EXISTS "booking_reference_seq";

ALTER TABLE "bookings" ADD COLUMN IF NOT EXISTS "reference" TEXT;

-- Backfill existing rows in creation order, keeping each booking's own year.
WITH numbered AS (
  SELECT
    id,
    row_number() OVER (ORDER BY created_at NULLS FIRST, id) AS n,
    to_char(timezone('Pacific/Auckland', COALESCE(created_at, now())), 'YYYY') AS yr
  FROM "bookings"
  WHERE reference IS NULL
)
UPDATE "bookings" b
SET reference = 'BK-' || numbered.yr || '-' || lpad(numbered.n::text, 5, '0')
FROM numbered
WHERE b.id = numbered.id;

-- Continue numbering after the backfill (is_called = false → nextval returns this value).
SELECT setval('booking_reference_seq', (SELECT count(*) FROM "bookings") + 1, false);

ALTER TABLE "bookings"
  ALTER COLUMN "reference" SET DEFAULT (
    'BK-' || to_char(timezone('Pacific/Auckland', now()), 'YYYY') || '-' ||
    lpad(nextval('booking_reference_seq')::text, 5, '0')
  );

ALTER TABLE "bookings" ALTER COLUMN "reference" SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "bookings_reference_key" ON "bookings"("reference");
